create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.subjects (id text primary key, title text not null, sequence int not null);
create table if not exists public.modules (id text primary key, subject_id text not null references public.subjects(id), title text not null, status text not null check (status in ('planned','draft','reviewed','published')), curriculum_version int not null default 1, content jsonb, sequence int not null);
create table if not exists public.sources (id uuid primary key default gen_random_uuid(), title text not null, url text not null unique, author text, revised text, resource_type text, why_useful text, checked_at date, access_status text);
create table if not exists public.module_sources (module_id text references public.modules(id), source_id uuid references public.sources(id), primary key(module_id,source_id));
create table if not exists public.notes (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, module_id text not null, body text not null check(char_length(body)<=10000), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.tutor_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, module_id text not null, started_at timestamptz not null default now(), ended_at timestamptz, retain_transcript boolean not null default false, messages jsonb not null default '[]'::jsonb);
create table if not exists public.assessment_attempts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, module_id text not null, submitted jsonb not null, feedback jsonb not null, rubric_version int not null default 1, created_at timestamptz not null default now());
create table if not exists public.learning_progress (user_id uuid not null references auth.users(id) on delete cascade, module_id text not null, state text not null check(state in ('not_started','reading','practicing','demonstrated','needs_review','mastered')), confidence int check(confidence between 1 and 5), updated_at timestamptz not null default now(), primary key(user_id,module_id));
create table if not exists public.review_tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, module_id text not null, due_at timestamptz not null, prompt text not null, completed_at timestamptz);
create table if not exists public.provider_usage (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, provider text not null, kind text not null, units numeric not null default 1, created_at timestamptz not null default now());
create table if not exists public.api_limits (user_id uuid not null references auth.users(id) on delete cascade, bucket text not null, period_start timestamptz not null, used int not null default 0, primary key(user_id,bucket));
create or replace function public.consume_limit(p_user uuid,p_bucket text,p_max int,p_window_seconds int) returns boolean language plpgsql security definer set search_path=public as $$ declare v_used int; begin if auth.uid() is distinct from p_user then return false; end if; insert into public.api_limits(user_id,bucket,period_start,used) values(p_user,p_bucket,now(),1) on conflict(user_id,bucket) do update set period_start=case when api_limits.period_start < now()-make_interval(secs=>p_window_seconds) then now() else api_limits.period_start end, used=case when api_limits.period_start < now()-make_interval(secs=>p_window_seconds) then 1 else api_limits.used+1 end returning used into v_used; return v_used<=p_max; end $$;
revoke all on function public.consume_limit(uuid,text,int,int) from public; grant execute on function public.consume_limit(uuid,text,int,int) to authenticated;
alter table public.profiles enable row level security; alter table public.subjects enable row level security; alter table public.modules enable row level security; alter table public.sources enable row level security; alter table public.module_sources enable row level security; alter table public.notes enable row level security; alter table public.tutor_sessions enable row level security; alter table public.assessment_attempts enable row level security; alter table public.learning_progress enable row level security; alter table public.review_tasks enable row level security; alter table public.provider_usage enable row level security; alter table public.api_limits enable row level security;
create policy own_profiles on public.profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy read_subjects on public.subjects for select to authenticated using(true);
create policy read_modules on public.modules for select to authenticated using(true);
create policy read_sources on public.sources for select to authenticated using(true);
create policy read_module_sources on public.module_sources for select to authenticated using(true);
create policy own_notes on public.notes for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy own_sessions on public.tutor_sessions for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy own_attempts on public.assessment_attempts for select to authenticated using(user_id=auth.uid());
create policy own_progress on public.learning_progress for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy own_reviews on public.review_tasks for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy own_usage on public.provider_usage for select to authenticated using(user_id=auth.uid());
create policy own_limits on public.api_limits for select to authenticated using(user_id=auth.uid());
